<script setup lang="ts">
import {formatDate} from '../ui/branding'
import {watch,ref} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage} from 'element-plus'
import {api,message} from '../api/client'
import ModelMappings from '../components/ModelMappings.vue'
import ProviderTestDialog from '../components/ProviderTestDialog.vue'
import {type Provider,type TestResult,healthLabels,authLabels,schedulingLabels,categoryLabels} from '../api/provider'
const usage=ref<any>(null),recent=ref<any[]>([]),failures=ref<any[]>([]),loading=ref(false)
const route=useRoute(),row=ref<Provider|null>(null),error=ref(''),testing=ref(false),result=ref<TestResult|null>(null)
const testDialog=ref(false)
async function openModelTest(){try{row.value=(await api.get('/admin/providers/'+route.params.id)).data.data;testDialog.value=true}catch(e){ElMessage.error(message(e))}}
let generation=0
async function load(){const mine=++generation;loading.value=true;error.value='';row.value=null;usage.value=null;recent.value=[];failures.value=[];try{const id=String(route.params.id);const [p,u,c,f]=await Promise.all([api.get('/admin/providers/'+id),api.get('/admin/usage',{params:{provider_id:id}}),api.get('/admin/call-logs',{params:{provider_id:id,page_size:5}}),api.get('/admin/call-logs',{params:{provider_id:id,status:'failed',page_size:5}})]);if(mine!==generation)return;row.value=p.data.data;usage.value=u.data.data.summary;recent.value=c.data.data.items.slice(0,5);failures.value=f.data.data.items.slice(0,5)}catch(e){if(mine===generation)error.value=message(e)}finally{if(mine===generation)loading.value=false}}
async function test(){testing.value=true;try{result.value=(await api.post('/admin/providers/'+route.params.id+'/test')).data.data;await load()}catch(e){ElMessage.error(message(e))}finally{testing.value=false}}
watch(()=>route.params.id,load,{immediate:true})
</script>
<template><div v-loading="loading"><el-button @click="$router.push('/admin/providers')">返回模型供应商</el-button><h1 style="margin-top:24px">账号详情</h1><el-alert v-if="error" :title="error" type="error"/><div class="panel" v-if="row"><div class="toolbar"><h2>{{row.name}}</h2><router-link :to="{path:'/admin/call-logs',query:{provider_id:String(row.id),status:'failed'}}"><el-button>查看失败调用</el-button></router-link><router-link :to="{path:'/admin/usage',query:{provider_id:String(row.id)}}"><el-button>查看账号用量</el-button></router-link><el-button type="primary" :disabled="row.status!=='enabled'" @click="openModelTest">测试模型</el-button><el-button :loading="testing" :disabled="row.status!=='enabled'" @click="test">连接检查</el-button></div><div class="provider-kpis"><div v-for="k in [{name:'当前并发',value:row.current_concurrency},{name:'近7天请求',value:usage?.requests},{name:'失败率 %',value:usage?.failure_rate},{name:'最近延迟 ms',value:row.last_latency_ms},{name:'平均 TTFT ms',value:usage?.average_ttft_ms}]" :key="k.name"><span class="muted">{{k.name}}</span><strong>{{k.value??'—'}}</strong></div></div><el-tabs><el-tab-pane label="基础配置"><el-descriptions :column="2" border><el-descriptions-item label="供应商">{{row.provider_type_name||row.provider_type}}</el-descriptions-item><el-descriptions-item label="协议类型">{{categoryLabels[row.effective_protocol_type||'']||'未配置'}}</el-descriptions-item><el-descriptions-item label="账号类型">{{row.account_type_name||row.account_type}}</el-descriptions-item><el-descriptions-item label="协议">{{row.protocol_config?Object.keys(row.protocol_config).join(' / '):row.protocol}}</el-descriptions-item><el-descriptions-item label="服务 URL" :span="2">{{row.protocol_config?Object.values(row.protocol_config)[0]?.api_url||row.base_url.replace(/\/$/,'')+(Object.values(row.protocol_config)[0]?.path_prefix||''):row.base_url}}</el-descriptions-item><el-descriptions-item v-for="(config,name) in row.protocol_config||{}" :key="name" :label="String(name)" :span="2">{{config.api_url||row.base_url.replace(/\/$/,'')+(config.path_prefix||'')}} · {{config.auth_type==='bearer'?'Bearer Token':'x-api-key'}}</el-descriptions-item><el-descriptions-item label="默认测试模型">{{row.default_test_model||'未指定'}}</el-descriptions-item><el-descriptions-item label="Key">{{row.has_api_key?'已配置，完整密钥不可查看':'未配置'}}</el-descriptions-item><el-descriptions-item label="代理">{{row.proxy||'未配置'}}</el-descriptions-item><el-descriptions-item label="状态">{{row.status==='enabled'?'启用':'禁用'}}</el-descriptions-item><el-descriptions-item label="健康状态">{{healthLabels[row.health_status]}}</el-descriptions-item><el-descriptions-item label="调度状态">{{schedulingLabels[row.scheduling_state]}}</el-descriptions-item><el-descriptions-item label="当前并发">{{row.current_concurrency??'不可读取'}}</el-descriptions-item><el-descriptions-item label="优先级">{{row.priority}}</el-descriptions-item><el-descriptions-item label="最大并发">{{row.max_concurrency}}</el-descriptions-item><el-descriptions-item label="失败次数">{{row.failure_count}}</el-descriptions-item><el-descriptions-item label="冷却至">{{row.cooldown_until?formatDate(row.cooldown_until):'无'}}</el-descriptions-item><el-descriptions-item label="最近测试">{{row.last_test_at?formatDate(row.last_test_at):'未测试'}}</el-descriptions-item><el-descriptions-item label="HTTP状态">{{row.last_http_status??'无'}}</el-descriptions-item><el-descriptions-item label="响应时间">{{row.last_latency_ms!==null?row.last_latency_ms+' ms':'无'}}</el-descriptions-item><el-descriptions-item label="错误代码">{{row.last_error_code||'无'}}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{row.remark||'无'}}</el-descriptions-item><el-descriptions-item label="创建时间">{{formatDate(row.created_at)}}</el-descriptions-item><el-descriptions-item label="更新时间">{{formatDate(row.updated_at)}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane label="模型映射"><ModelMappings :provider-id="row.id" :enabled="row.status==='enabled'" :category="row.protocol_type"/></el-tab-pane><el-tab-pane label="运行状态"><el-descriptions :column="2" border><el-descriptions-item label="调度">{{schedulingLabels[row.scheduling_state]}}</el-descriptions-item><el-descriptions-item label="并发">{{row.current_concurrency??'未知'}} / {{row.max_concurrency}}</el-descriptions-item><el-descriptions-item label="健康">{{healthLabels[row.health_status]}}</el-descriptions-item><el-descriptions-item label="最近错误">{{row.last_error_code||'—'}}</el-descriptions-item></el-descriptions></el-tab-pane><el-tab-pane v-for="(items,label) in {最近调用:recent,最近错误:failures}" :key="label" :label="label"><el-table :data="items"><el-table-column label="Request ID" min-width="290"><template #default="s"><router-link class="route-link" :to="'/admin/call-logs/'+s.row.request_id">{{s.row.request_id}}</router-link></template></el-table-column><el-table-column prop="request_model" label="模型"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.error_code==='CONTENT_BLOCKED'?'danger':s.row.status==='success'?'success':s.row.status==='failure'?'danger':'info'">{{s.row.error_code==='CONTENT_BLOCKED'?'Block 拦截':s.row.status==='success'?'成功':s.row.status==='failure'?'失败':'客户端取消'}}</el-tag></template></el-table-column><el-table-column prop="error_code" label="错误码"/><template #empty><EmptyState title="暂无调用记录" description="近7天该账号暂无对应记录。"/></template></el-table></el-tab-pane></el-tabs></div><div class="panel" v-if="result"><el-alert :title="result.message" :type="result.success?'success':'error'" :closable="false"/><p>网络：{{result.network_connected?'已连接':'未确认连接'}} · 鉴权：{{authLabels[result.authentication]}} · HTTP {{result.http_status??'无响应'}} · {{result.latency_ms}} ms</p></div><ProviderTestDialog v-model="testDialog" :provider="row" @finished="load"/></div></template>


<style scoped>.provider-kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:16px;margin-bottom:24px}.provider-kpis>div{border:1px solid var(--line);border-radius:8px;padding:16px}.provider-kpis strong{display:block;font-size:26px;margin-top:8px}@media(max-width:1000px){.provider-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>